/**
 * OWNER SR,27 October2026 08:00 Fortaleza (docs/stripe-platform-eligibility.md):
 * country eligibility is NOT established by this payload or COUNTRIES.
 * For contradictory Stripe replies the less favorable answer applies until a
 * later complete, non-contradictory reply: BR platform connects BR creators only;
 * US platform planning requires SSN/ITIN, a US-resident legal representative and
 * a real US business address, not a PO box. These are owner-reported answers,
 * not verified platform-account approval. Earlier design rationale below is
 * retained as history; it cannot override SR or establish cross-border access.
 * SR2 separately requires dated company-account/direct-charge eligibility proof
 * before opening. No account, country list, fee, loss or release flag changes here.
 *
 * Connecting a creator's own Stripe account.
 *
 * The creator ends up owning a full Stripe account: their name on it, their
 * dashboard, their payouts, their money. Marktmorgen holds the account's identifier
 * and nothing else — no key to it, and never the money that lands in it. That
 * is what lets the site say the buyer pays into the creator's own account
 * without stretching the truth.
 *
 * Accounts v2, because Stripe now refuses v1 account creation for new Connect
 * integrations and points here. The shape below is not a style choice:
 *
 *   dashboard: "full"        the creator logs into Stripe itself
 *   fees_collector: stripe   Stripe bills them, not us
 *   losses_collector: stripe disputes and refunds are theirs, settled with Stripe
 *
 * Those three together are what Stripe calls a full-dashboard account, and it
 * is the only arrangement a platform registered in one country may open for a
 * creator in another. The platform-controlled variants — a dashboard we own,
 * fees and losses collected by us — are refused across a border. So the honest
 * design and the possible design are the same design here.
 */
import { STRIPE_TIMEOUT_MS, timed } from "@/lib/fetch-timeout";
import { DEMO_CONNECTED_ACCOUNT } from "@/lib/demo-account";

/** Local tests may point this at a mock on 127.0.0.1; nothing else is taken. */
const STRIPE_ROOT = /^http:\/\/127\.0\.0\.1:\d+$/.test(
  process.env.STRIPE_CONNECT_API_BASE ?? "",
)
  ? (process.env.STRIPE_CONNECT_API_BASE as string)
  : "https://api.stripe.com";

/**
 * Pinned on purpose.
 *
 * This file reads specific fields out of specific shapes. Letting the account's
 * default version float means a Stripe release could quietly change what
 * `capabilities.card_payments.status` looks like and the site would start
 * telling creators the wrong thing about their own money.
 */
export const STRIPE_VERSION = "2026-08-26.dahlia";

/** A link Stripe hands back is short-lived and single use. */
export const ONBOARDING_LINK_TTL_SECONDS = 5 * 60;

function platformKey(): string | null {
  const key = process.env.STRIPE_SECRET_KEY?.trim();
  if (!key || !/^(sk|rk)_(test|live)_/.test(key)) return null;
  return key;
}

export function isConnectConfigured(): boolean {
  return platformKey() !== null;
}

/** True when the platform key is a test key, so the UI can say so plainly. */
export function isConnectInTestMode(): boolean {
  return /^(sk|rk)_test_/.test(process.env.STRIPE_SECRET_KEY?.trim() ?? "");
}

/**
 * Whether what this store sells is paid for in Stripe's test mode: the site
 * as a whole is, or the store charges the demo's account. Asked of the store
 * and not only of our own key, because the demo store stays in test mode on
 * the day everything else stops being (lib/demo-account.ts).
 */
export function sellsInTestMode(store: { stripeAccountId: string | null }): boolean {
  return store.stripeAccountId === DEMO_CONNECTED_ACCOUNT || isConnectInTestMode();
}

/**
 * Carries what Stripe actually said.
 *
 * An earlier version of this file kept only the error code and threw the
 * message away. A creator then hit a plain "400 invalid_request_error" in the
 * logs and the reason — that the whole endpoint had been retired — took a trip
 * through the Stripe dashboard to find. The message is the useful part.
 */
export class StripeConnectError extends Error {
  readonly status: number;
  readonly code: string;
  readonly stripeMessage: string;

  constructor(status: number, code: string, stripeMessage: string) {
    super(`Stripe request failed (${status} ${code}): ${stripeMessage}`);
    this.status = status;
    this.code = code;
    this.stripeMessage = stripeMessage;
  }

  /** The creator's country is one this platform may not open an account in. */
  get isCrossBorderRefusal(): boolean {
    return this.code === "cross_border_connected_account_creation_not_allowed";
  }
}

async function stripeRequest(
  method: "GET" | "POST",
  path: string,
  body?: unknown,
): Promise<Record<string, unknown>> {
  const key = platformKey();
  if (!key) throw new Error("Stripe is not configured");

  // Given up after STRIPE_TIMEOUT_MS as a network failure is (lib/fetch-timeout.ts).
  const { response, data } = await timed(STRIPE_TIMEOUT_MS, async (signal) => {
    const response = await fetch(`${STRIPE_ROOT}${path}`, {
      method,
      headers: {
        Authorization: `Bearer ${key}`,
        "Stripe-Version": STRIPE_VERSION,
        // API v2 speaks JSON, unlike the form-encoded v1 endpoints.
        ...(body === undefined ? {} : { "Content-Type": "application/json" }),
      },
      body: body === undefined ? undefined : JSON.stringify(body),
      cache: "no-store",
      signal,
    });
    const data = (await response.json().catch(() => ({}))) as Record<string, unknown>;
    return { response, data };
  });
  if (!response.ok) {
    const error = data.error as
      | { code?: string; type?: string; message?: string }
      | undefined;
    throw new StripeConnectError(
      response.status,
      error?.code ?? error?.type ?? "unknown",
      error?.message ?? "Stripe gave no reason.",
    );
  }
  return data;
}

/**
 * The countries a creator can pick from.
 *
 * Every country where Stripe opens accounts for businesses in general — the
 * list it publishes as "Stripe-supported countries" — except the ones it
 * offers only by invitation or in preview, and except Brazil, which this
 * company does not sell into — and where, by Stripe's own rule, a platform
 * based outside Brazil may not take an application fee at all, so a store
 * there could not pay the share of each sale its plan is priced with
 * (lib/platform-share.ts; tests/platform-share.test.ts holds this). The six most creators choose come first; the
 * rest follow in alphabetical order.
 *
 * One list, used both to draw the menu and to check what comes back, so the
 * form can never accept something it did not offer. Stripe may still refuse a
 * country on this list — its rules change and they depend on where our own
 * account is registered — and that refusal is reported as itself rather than
 * as a generic failure.
 *
 * Stripe support, 28 October 2026 (thread "Connect platform eligibility for
 * international accounts", docs/stripe-platform-eligibility.md), for a US
 * platform taking direct charges on Standard accounts with no application
 * fee: available in each country below; not available in Malaysia, so
 * Malaysia is no longer offered; Brazil is a public beta and India is by
 * invitation only, so neither is offered. tests/connect-configuration.test.ts
 * holds the list to that answer.
 */
export const COUNTRIES: { code: string; name: string; top?: true }[] = [
  { code: "us", name: "United States", top: true },
  { code: "gb", name: "United Kingdom", top: true },
  { code: "ca", name: "Canada", top: true },
  { code: "au", name: "Australia", top: true },
  { code: "ie", name: "Ireland", top: true },
  { code: "nz", name: "New Zealand", top: true },
  { code: "at", name: "Austria" },
  { code: "be", name: "Belgium" },
  { code: "bg", name: "Bulgaria" },
  { code: "hr", name: "Croatia" },
  { code: "cy", name: "Cyprus" },
  { code: "cz", name: "Czech Republic" },
  { code: "dk", name: "Denmark" },
  { code: "ee", name: "Estonia" },
  { code: "fi", name: "Finland" },
  { code: "fr", name: "France" },
  { code: "de", name: "Germany" },
  { code: "gi", name: "Gibraltar" },
  { code: "gr", name: "Greece" },
  { code: "hk", name: "Hong Kong" },
  { code: "hu", name: "Hungary" },
  { code: "it", name: "Italy" },
  { code: "jp", name: "Japan" },
  { code: "lv", name: "Latvia" },
  { code: "li", name: "Liechtenstein" },
  { code: "lt", name: "Lithuania" },
  { code: "lu", name: "Luxembourg" },
  { code: "mt", name: "Malta" },
  { code: "mx", name: "Mexico" },
  { code: "nl", name: "Netherlands" },
  { code: "no", name: "Norway" },
  { code: "pl", name: "Poland" },
  { code: "pt", name: "Portugal" },
  { code: "ro", name: "Romania" },
  { code: "sg", name: "Singapore" },
  { code: "sk", name: "Slovakia" },
  { code: "si", name: "Slovenia" },
  { code: "es", name: "Spain" },
  { code: "se", name: "Sweden" },
  { code: "ch", name: "Switzerland" },
  { code: "th", name: "Thailand" },
  { code: "ae", name: "United Arab Emirates" },
];

const OFFERED = new Set(COUNTRIES.map((country) => country.code));

/** Empty for anything we did not put on the menu ourselves. */
export function normaliseCountry(value: string): string {
  const trimmed = value.trim().toLowerCase();
  return OFFERED.has(trimmed) ? trimmed : "";
}

/**
 * Opens a Stripe account that belongs to the creator.
 *
 * The country has to be settled here, before Stripe's onboarding starts, and
 * it cannot be changed afterward — which is why the studio asks for it in
 * plain words rather than guessing from an IP address.
 *
 * The store's own address is left for onboarding to collect. Stripe asks the
 * creator for their business URL there, and an answer they gave themselves is
 * worth more on their account than one we filled in for them.
 */
export async function createConnectedAccount(options: {
  email: string;
  country: string;
  displayName: string;
}): Promise<string> {
  const country = normaliseCountry(options.country);
  if (!country) throw new Error("A country is needed to open an account");

  const account = await stripeRequest("POST", "/v2/core/accounts", {
    contact_email: options.email,
    display_name: options.displayName,
    dashboard: "full",
    identity: { country },
    configuration: {
      merchant: { capabilities: { card_payments: { requested: true } } },
    },
    defaults: {
      responsibilities: {
        fees_collector: "stripe",
        losses_collector: "stripe",
      },
    },
  });

  const id = account.id;
  if (typeof id !== "string" || !id) {
    throw new Error("Stripe did not return an account id");
  }
  return id;
}

/**
 * The one-time link that takes the creator into Stripe's own onboarding.
 *
 * Stripe is explicit that these must never be emailed or passed around: they
 * open a door to the account holder's personal information, so this link only
 * ever goes to a browser that has just proved it holds the session.
 *
 * `storeId` names the store the way back is for, so a creator with several
 * stores comes back to the one whose account they were finishing.
 */
export async function createOnboardingLink(
  accountId: string,
  origin: string,
  storeId = "",
): Promise<string> {
  const pin = /^[0-9a-f]{32}$/.test(storeId) ? `?store=${storeId}` : "";
  const link = await stripeRequest("POST", "/v2/core/account_links", {
    account: accountId,
    use_case: {
      type: "account_onboarding",
      account_onboarding: {
        configurations: ["merchant"],
        refresh_url: `${origin}/api/stripe/refresh${pin}`,
        return_url: `${origin}/api/stripe/return${pin}`,
      },
    },
  });

  if (typeof link.url !== "string" || !link.url) {
    throw new Error("Stripe did not return an onboarding link");
  }
  return link.url;
}

export type AccountState = {
  chargesEnabled: boolean;
  detailsSubmitted: boolean;
};

/** A JSON object, never null or an array. */
function objectOf(value: unknown): Record<string, unknown> | null {
  return value !== null && typeof value === "object" && !Array.isArray(value) ? (value as Record<string, unknown>) : null;
}

/** Thrown where Stripe's account answer is not in its exact shape: nothing about the account is known. */
function unknownShape(what: string): never {
  throw new Error(`Stripe answered ${what} in an unknown shape`);
}

/**
 * The card_payments status, read exactly: the account, configuration.merchant,
 * its capabilities and card_payments are objects and the status one of
 * CARD_STATUSES. A 200 that says less (the include ignored, a change of shape, a body
 * that is not JSON) is unknown, never "card payments off" (CX-123 rule 24).
 */
// The statuses read as known, from Stripe's own generated v2 types for the pinned API version (stripe-node v22.6.0,
// API 2026-08-26.dahlia, src/resources/V2/Core/Accounts.ts): card_payments is active | pending | restricted |
// unsupported. Anything else (another value such as v1's "inactive", another letter case, blank) is unknown and
// throws, so nothing is written on it (Codex Z and Codex U on #3311): a value Stripe adds later reads as "not
// checked" until it is added here, never as "card payments off".
const CARD_STATUSES = new Set(["active", "pending", "restricted", "unsupported"]);
// The statuses of a requirements deadline (same source): currently_due | eventually_due | past_due.
const DEADLINE_STATUSES = new Set(["currently_due", "eventually_due", "past_due"]);

function cardPaymentsStatus(account: unknown): string {
  const configuration = objectOf(objectOf(account)?.configuration);
  const merchant = objectOf(configuration?.merchant);
  const cardPayments = objectOf(objectOf(merchant?.capabilities)?.card_payments);
  const status = cardPayments?.status;
  if (typeof status !== "string" || !CARD_STATUSES.has(status)) unknownShape("an account's card payments");
  return status;
}

/**
 * The status of the earliest requirements deadline, or null when Stripe says
 * there is none: `requirements` or its `summary` null, or a summary without a
 * minimum_deadline (or with it null). A missing `requirements` or `summary`, or
 * any other shape, is unknown, never "nothing outstanding" (CX-123 rule 24).
 */
function deadlineStatus(account: unknown): string | null {
  const raw = objectOf(account)?.requirements;
  if (raw === null) return null;
  const requirements = objectOf(raw) ?? unknownShape("an account's requirements");
  if (requirements.summary === null) return null;
  const summary = objectOf(requirements.summary) ?? unknownShape("an account's requirements summary");
  if (summary.minimum_deadline === undefined || summary.minimum_deadline === null) return null;
  const status = objectOf(summary.minimum_deadline)?.status;
  if (typeof status !== "string" || !DEADLINE_STATUSES.has(status)) unknownShape("an account's requirements deadline");
  return status;
}

/**
 * Asks Stripe what that account can actually do right now.
 *
 * Read every time rather than remembered, because a capability can be switched
 * off by Stripe hours after onboarding finished, and a store that says "buy"
 * over a dead account wastes a buyer's time and the creator's reputation.
 */
export async function readAccount(accountId: string): Promise<AccountState> {
  const account = await stripeRequest(
    "GET",
    `/v2/core/accounts/${encodeURIComponent(accountId)}` +
      "?include=configuration.merchant&include=requirements",
  );

  // Read exactly (CX-123 rule 24): an unknown shape throws, so the studio routes
  // answer "stripe=error" and write nothing, and the checkup says "not-checked".
  const status = cardPaymentsStatus(account);
  const deadline = deadlineStatus(account);

  return {
    chargesEnabled: status === "active",
    // Onboarding still has something outstanding while a deadline is past due.
    detailsSubmitted: deadline !== "past_due",
  };
}

// CX-123 rule 24, at readAccount (lib/stripe-connect.ts): Stripe's answer about a
// connected account is read in its exact shape. A 200 without
// configuration.merchant (the include ignored, a change of shape in API v2, a
// body that is not JSON) was read as "card payments off", and the studio routes
// app/api/stripe/check and app/api/stripe/return wrote that down with
// setStripeAccount: a selling store's checkout closed and the creator read
// "stripe=pending" while nothing was known. A 200 without `requirements` was read
// as "nothing outstanding", so the checkup said all was fine and never warned of
// a documents deadline that had passed. Now any other shape throws: the routes
// answer "stripe=error" and write nothing, the checkup says "not-checked".
// Synthetic store, synthetic session, Stripe mocked; MemoryRedis (tests/redis-stub.ts).
import { NextRequest } from "next/server";
import { GET as returnGET } from "@/app/api/stripe/return/route";
import { POST as checkPOST } from "@/app/api/stripe/check/route";
import { SESSION_COOKIE, openSession } from "@/lib/auth";
import { within } from "@/lib/checkup";
import { stripeCheck } from "@/lib/checkup-rules";
import { readAccount } from "@/lib/stripe-connect";
import { claimHandle, setStripeAccount, storeForEmail } from "@/lib/store";
import "./redis-stub";
import { done, is, part } from "./check";

process.env.STRIPE_SECRET_KEY = "sk_test_connect_account_exact_only";
const ACCOUNT = "acct_1ExactShape";

/** The body Stripe answers with, as raw text so a body that is not JSON can be sent too. */
let body = "";
let stripeCalls = 0;
globalThis.fetch = (async (input: string | URL | Request) => {
  const url = new URL(String(input));
  if (url.origin !== "https://api.stripe.com" || !url.pathname.startsWith(`/v2/core/accounts/${ACCOUNT}`)) {
    throw new Error(`Unexpected synthetic provider request: ${url}`);
  }
  stripeCalls++;
  return new Response(body, { status: 200, headers: { "content-type": "application/json" } });
}) as typeof fetch;

const card = (status: unknown) => ({ merchant: { capabilities: { card_payments: { status } } } });
const shaped = (status: unknown, requirements: unknown) => JSON.stringify({ id: ACCOUNT, configuration: card(status), requirements });

/** Shapes that say nothing certain: each must throw, never read as "off" or "nothing due". */
const UNKNOWN: ReadonlyArray<readonly [string, string]> = [
  ["no configuration (the include ignored)", JSON.stringify({ id: ACCOUNT, requirements: { summary: {} } })],
  ["configuration not an object", JSON.stringify({ id: ACCOUNT, configuration: "merchant", requirements: { summary: {} } })],
  ["no merchant", JSON.stringify({ id: ACCOUNT, configuration: {}, requirements: { summary: {} } })],
  ["merchant null", JSON.stringify({ id: ACCOUNT, configuration: { merchant: null }, requirements: { summary: {} } })],
  ["no capabilities", JSON.stringify({ id: ACCOUNT, configuration: { merchant: {} }, requirements: { summary: {} } })],
  ["no card_payments", JSON.stringify({ id: ACCOUNT, configuration: { merchant: { capabilities: {} } }, requirements: { summary: {} } })],
  ["card_payments an array", JSON.stringify({ id: ACCOUNT, configuration: { merchant: { capabilities: { card_payments: ["active"] } } }, requirements: { summary: {} } })],
  ["status missing", JSON.stringify({ id: ACCOUNT, configuration: { merchant: { capabilities: { card_payments: {} } } }, requirements: { summary: {} } })],
  ["status a number", shaped(1, { summary: {} })],
  ["status empty", shaped("", { summary: {} })],
  ["status null", shaped(null, { summary: {} })],
  ["no requirements, card payments active", JSON.stringify({ id: ACCOUNT, configuration: card("active") })],
  ["requirements a string", shaped("active", "none")],
  ["requirements an array", shaped("active", [])],
  ["requirements without summary", shaped("active", {})],
  ["summary a string", shaped("active", { summary: "ok" })],
  ["summary an array", shaped("active", { summary: [] })],
  ["minimum_deadline a string", shaped("active", { summary: { minimum_deadline: "past_due" } })],
  ["minimum_deadline an array", shaped("active", { summary: { minimum_deadline: [] } })],
  ["minimum_deadline without status", shaped("active", { summary: { minimum_deadline: {} } })],
  ["minimum_deadline status a number", shaped("active", { summary: { minimum_deadline: { status: 3 } } })],
  // Codex Z on #3311 (review 5820295862): a status that is not one Stripe documents is not known either.
  // "inactive" is a v1 Capability status, not one of the v2 card_payments statuses (stripe-node v22.6.0, API
  // 2026-08-26.dahlia: active | pending | restricted | unsupported), so it is unknown here (Codex U on #3311).
  ["card status 'inactive' (v1, not a v2 status)", shaped("inactive", { summary: {} })],
  ["card status a single space", shaped(" ", { summary: {} })],
  ["card status a value Stripe does not document", shaped("future_unknown", { summary: {} })],
  ["card status in other letter case", shaped("Active", { summary: {} })],
  ["deadline status a value Stripe does not document", shaped("active", { summary: { minimum_deadline: { status: "someday_due" } } })],
  ["deadline status empty", shaped("active", { summary: { minimum_deadline: { status: "" } } })],
  ["only an id", JSON.stringify({ id: ACCOUNT })],
  ["empty object", "{}"],
  ["JSON null", "null"],
  ["JSON array", "[]"],
  ["JSON number", "7"],
  ["not JSON", "<html>maintenance</html>"],
];

/** Confirmed shapes, read as before. */
const HEALTHY: ReadonlyArray<readonly [string, string, { chargesEnabled: boolean; detailsSubmitted: boolean }]> = [
  ["active, eventually due", shaped("active", { summary: { minimum_deadline: { status: "eventually_due" } } }), { chargesEnabled: true, detailsSubmitted: true }],
  ["active, currently due", shaped("active", { summary: { minimum_deadline: { status: "currently_due" } } }), { chargesEnabled: true, detailsSubmitted: true }],
  ["active, past due", shaped("active", { summary: { minimum_deadline: { status: "past_due" } } }), { chargesEnabled: true, detailsSubmitted: false }],
  ["restricted, past due", shaped("restricted", { summary: { minimum_deadline: { status: "past_due" } } }), { chargesEnabled: false, detailsSubmitted: false }],
  ["pending, nothing due (empty summary)", shaped("pending", { summary: {} }), { chargesEnabled: false, detailsSubmitted: true }],
  ["active, minimum_deadline null (nothing due)", shaped("active", { summary: { minimum_deadline: null } }), { chargesEnabled: true, detailsSubmitted: true }],
  ["active, summary null (confirmed none)", shaped("active", { summary: null }), { chargesEnabled: true, detailsSubmitted: true }],
  ["active, requirements null (confirmed none)", shaped("active", null), { chargesEnabled: true, detailsSubmitted: true }],
  ["unsupported, nothing due", shaped("unsupported", { summary: {} }), { chargesEnabled: false, detailsSubmitted: true }],
];

async function read(): Promise<string> {
  try {
    return JSON.stringify(await readAccount(ACCOUNT));
  } catch {
    return "threw";
  }
}

async function main() {
  part("readAccount: every unknown shape throws");
  for (const [label, reply] of UNKNOWN) {
    body = reply;
    is(`${label}: throws`, await read(), "threw");
  }

  part("readAccount: confirmed shapes read as before");
  for (const [label, reply, want] of HEALTHY) {
    body = reply;
    is(`${label}: read`, await read(), JSON.stringify(want));
  }

  part("checkup: an unknown shape is said as not checked, never as fine");
  for (const [label, reply] of [UNKNOWN[0], UNKNOWN[11]] as const) {
    body = reply;
    const account = await within(() => readAccount(ACCOUNT), null, 2_000);
    is(`${label}: payments line`, stripeCheck(true, account).state, "not-checked");
  }
  body = shaped("active", { summary: { minimum_deadline: { status: "past_due" } } });
  is("control, past due: warned", stripeCheck(true, await within(() => readAccount(ACCOUNT), null, 2_000)).state === "ok", false);
  body = shaped("active", { summary: {} });
  is("control, nothing due: ok", stripeCheck(true, await within(() => readAccount(ACCOUNT), null, 2_000)).state, "ok");

  const email = "connect-exact@example.com";
  is("synthetic store", (await claimHandle(email, "connectexact", "A store", "")).ok, true);
  const session = await openSession(email);
  const cookie = `${SESSION_COOKIE}=${session}`;
  const routes = [
    ["return", () => returnGET(new NextRequest("https://marktmorgen.com/api/stripe/return", { headers: { cookie } }))],
    ["check", () => checkPOST(new NextRequest("https://marktmorgen.com/api/stripe/check", { method: "POST", headers: { cookie, origin: "https://marktmorgen.com", host: "marktmorgen.com" } }))],
  ] as const;
  const said = (response: Response) => new URL(response.headers.get("location") ?? "", "https://marktmorgen.com").searchParams.get("stripe");

  for (const [name, call] of routes) {
    part(`${name}: an unknown shape writes nothing and says the check failed`);
    for (const [label, reply] of [UNKNOWN[0], UNKNOWN[2], UNKNOWN[11], UNKNOWN[26]] as const) {
      is("seeded selling", (await setStripeAccount(email, ACCOUNT, true)).ok, true);
      body = reply;
      stripeCalls = 0;
      const response = await call();
      is(`${name} ${label}: told the check failed`, said(response), "error");
      is(`${name} ${label}: the selling record is unchanged`, (await storeForEmail(email))?.stripeChargesEnabled, true);
      is(`${name} ${label}: Stripe asked once`, stripeCalls, 1);
    }

    part(`${name}: confirmed shapes are written and said as before`);
    for (const [status, charges, word] of [["active", true, "ready"], ["pending", false, "pending"]] as const) {
      is("seeded", (await setStripeAccount(email, ACCOUNT, !charges)).ok, true);
      body = shaped(status, { summary: {} });
      const response = await call();
      is(`${name} ${status}: said`, said(response), word);
      is(`${name} ${status}: written`, (await storeForEmail(email))?.stripeChargesEnabled, charges);
    }
  }
  done();
}

void main();

