const OFFERED = new Set(COUNTRIES.map((country) => country.code));

/** Empty for anything we did not put on the menu ourselves. */
export function normaliseCountry(value: string): string {
  const trimmed = value.trim().toLowerCase();
  return OFFERED.has(trimmed) ? trimmed : "";
}

/**
 * Opens a Stripe account that belongs to the creator.
 *
 * The country has to be settled here, before Stripe's onboarding starts, and
 * it cannot be changed afterward — which is why the studio asks for it in
 * plain words rather than guessing from an IP address.
 *
 * The store's own address is left for onboarding to collect. Stripe asks the
 * creator for their business URL there, and an answer they gave themselves is
 * worth more on their account than one we filled in for them.
 */
export async function createConnectedAccount(options: {
  email: string;
  country: string;
  displayName: string;
}): Promise<string> {
  const country = normaliseCountry(options.country);
  if (!country) throw new Error("A country is needed to open an account");

  const account = await stripeRequest("POST", "/v2/core/accounts", {
    contact_email: options.email,
    display_name: options.displayName,
    dashboard: "full",
    identity: { country },
    configuration: {
      merchant: { capabilities: { card_payments: { requested: true } } },
    },
    defaults: {
      responsibilities: {
        fees_collector: "stripe",
        losses_collector: "stripe",
      },
    },
  });

  const id = account.id;
  if (typeof id !== "string" || !id) {
    throw new Error("Stripe did not return an account id");
  }
  return id;
}

/**
 * The one-time link that takes the creator into Stripe's own onboarding.
 *
 * Stripe is explicit that these must never be emailed or passed around: they
 * open a door to the account holder's personal information, so this link only
 * ever goes to a browser that has just proved it holds the session.
 *
 * `storeId` names the store the way back is for, so a creator with several
 * stores comes back to the one whose account they were finishing.
 */
export async function createOnboardingLink(
  accountId: string,
  origin: string,
  storeId = "",
): Promise<string> {
  const pin = /^[0-9a-f]{32}$/.test(storeId) ? `?store=${storeId}` : "";
  const link = await stripeRequest("POST", "/v2/core/account_links", {
    account: accountId,
    use_case: {
      type: "account_onboarding",
      account_onboarding: {
        configurations: ["merchant"],
        refresh_url: `${origin}/api/stripe/refresh${pin}`,
        return_url: `${origin}/api/stripe/return${pin}`,
      },
    },
  });

  if (typeof link.url !== "string" || !link.url) {
    throw new Error("Stripe did not return an onboarding link");
  }
  return link.url;
}

export type AccountState = {
  chargesEnabled: boolean;
  detailsSubmitted: boolean;
};

/** A JSON object, never null or an array. */
function objectOf(value: unknown): Record<string, unknown> | null {
  return value !== null && typeof value === "object" && !Array.isArray(value) ? (value as Record<string, unknown>) : null;
}

/** Thrown where Stripe's account answer is not in its exact shape: nothing about the account is known. */
function unknownShape(what: string): never {
  throw new Error(`Stripe answered ${what} in an unknown shape`);
}

/**
 * The card_payments status, read exactly: the account, configuration.merchant,
 * its capabilities and card_payments are objects and the status one of
 * CARD_STATUSES. A 200 that says less (the include ignored, a change of shape, a body
 * that is not JSON) is unknown, never "card payments off" (CX-123 rule 24).
 */
// The statuses read as known. Stripe's v2 capability statuses are active, pending, restricted and unsupported;
// "inactive" is kept as an "off" answer the earlier code and tests already took as Stripe's. Anything else (another
// value, another letter case, blank) is unknown and throws, so nothing is written on it (Codex Z on #3311): a value
// Stripe adds later reads as "not checked" until it is added here, never as "card payments off".
const CARD_STATUSES = new Set(["active", "inactive", "pending", "restricted", "unsupported"]);
// The statuses of a requirements deadline: currently_due, eventually_due and past_due.
const DEADLINE_STATUSES = new Set(["currently_due", "eventually_due", "past_due"]);

function cardPaymentsStatus(account: unknown): string {
  const configuration = objectOf(objectOf(account)?.configuration);
  const merchant = objectOf(configuration?.merchant);
  const cardPayments = objectOf(objectOf(merchant?.capabilities)?.card_payments);
  const status = cardPayments?.status;
  if (typeof status !== "string" || !CARD_STATUSES.has(status)) unknownShape("an account's card payments");
  return status;
}

/**
 * The status of the earliest requirements deadline, or null when Stripe says
 * there is none: `requirements` or its `summary` null, or a summary without a
 * minimum_deadline (or with it null). A missing `requirements` or `summary`, or
 * any other shape, is unknown, never "nothing outstanding" (CX-123 rule 24).
 */
function deadlineStatus(account: unknown): string | null {
  const raw = objectOf(account)?.requirements;
  if (raw === null) return null;
  const requirements = objectOf(raw) ?? unknownShape("an account's requirements");
  if (requirements.summary === null) return null;
  const summary = objectOf(requirements.summary) ?? unknownShape("an account's requirements summary");
  if (summary.minimum_deadline === undefined || summary.minimum_deadline === null) return null;
  const status = objectOf(summary.minimum_deadline)?.status;
  if (typeof status !== "string" || !DEADLINE_STATUSES.has(status)) unknownShape("an account's requirements deadline");
  return status;
}

/**
 * Asks Stripe what that account can actually do right now.
 *
 * Read every time rather than remembered, because a capability can be switched
 * off by Stripe hours after onboarding finished, and a store that says "buy"
 * over a dead account wastes a buyer's time and the creator's reputation.
 */
export async function readAccount(accountId: string): Promise<AccountState> {
  const account = await stripeRequest(
    "GET",
    `/v2/core/accounts/${encodeURIComponent(accountId)}` +
      "?include=configuration.merchant&include=requirements",
  );

  // Read exactly (CX-123 rule 24): an unknown shape throws, so the studio routes
  // answer "stripe=error" and write nothing, and the checkup says "not-checked".
  const status = cardPaymentsStatus(account);
  const deadline = deadlineStatus(account);

  return {
    chargesEnabled: status === "active",
    // Onboarding still has something outstanding while a deadline is past due.
    detailsSubmitted: deadline !== "past_due",
  };
}
